const input = $input.first().json;

const prompt = input.prompt;
const policyName = input.policy_name || 'manual';
const maxTokens = Number(input.max_tokens || 256);
const runsPerModel = Math.max(1, Number(input.runs_per_model || 3));
const benchmarkId = `bench-${Date.now()}`;

const localUrl = $env.LOCAL_AI_BASE_URL || 'http://host.docker.internal:18180/v1/chat/completions';
const cloudUrl = $env.CLOUD_AI_BASE_URL || '';
const cloudApiKey = $env.CLOUD_AI_API_KEY || '';

const models = [
  {
    provider: 'local',
    label: 'local-qwen',
    url: localUrl,
    model: $env.LOCAL_AI_MODEL || 'qwen3.5:4b',
    apiKey: '',
    inputRate: Number($env.LOCAL_AI_INPUT_USD_PER_1K || 0),
    outputRate: Number($env.LOCAL_AI_OUTPUT_USD_PER_1K || 0)
  },
  {
    provider: 'cloud',
    label: 'gemini-flash-lite',
    url: cloudUrl,
    model: $env.CLOUD_AI_MODEL || '',
    apiKey: cloudApiKey,
    inputRate: Number($env.CLOUD_AI_INPUT_USD_PER_1K || 0),
    outputRate: Number($env.CLOUD_AI_OUTPUT_USD_PER_1K || 0)
  },
  {
    provider: 'cloud',
    label: 'gemma-4-26b',
    url: cloudUrl,
    model: $env.CLOUD_AI_MODEL_ALT || '',
    apiKey: cloudApiKey,
    inputRate: Number($env.CLOUD_AI_ALT_INPUT_USD_PER_1K || $env.CLOUD_AI_INPUT_USD_PER_1K || 0),
    outputRate: Number($env.CLOUD_AI_ALT_OUTPUT_USD_PER_1K || $env.CLOUD_AI_OUTPUT_USD_PER_1K || 0)
  }
];

function buildBody(model) {
  return {
    model,
    temperature: 0.2,
    max_tokens: maxTokens,
    messages: [
      {
        role: 'system',
        content: [
          `Use policy ${policyName}.`,
          'Write in Traditional Chinese for Taiwan readers.',
          'Do not reveal hidden reasoning, chain-of-thought, or <think> blocks.',
          'Return only the final answer text.'
        ].join('\n')
      },
      { role: 'user', content: prompt }
    ]
  };
}

function usageOf(result) {
  const usage = result.usage || {};
  const promptTokens = Number(usage.prompt_tokens || usage.input_tokens || 0);
  const completionTokens = Number(usage.completion_tokens || usage.output_tokens || 0);
  const totalTokens = Number(usage.total_tokens || promptTokens + completionTokens || 0);
  return { promptTokens, completionTokens, totalTokens };
}

function estimateCost(usage, inputRate, outputRate) {
  return (usage.promptTokens / 1000) * inputRate + (usage.completionTokens / 1000) * outputRate;
}

function textQuality(content, error) {
  const text = String(content || '');
  const hasThoughtLeak = /<think>|<thought>|Thinking Process|chain[- ]of[- ]thought/i.test(text);
  const hasTraditionalChinese = /[\u4e00-\u9fff]/.test(text);
  const hasFbShape = /。|！|？|\n/.test(text) || text.length >= 80;
  let score = 0;
  if (!error) score += 30;
  if (text.trim().length > 0) score += 20;
  if (!hasThoughtLeak) score += 25;
  if (hasTraditionalChinese) score += 15;
  if (hasFbShape) score += 10;
  return {
    quality_score: score,
    has_thought_leak: hasThoughtLeak,
    has_traditional_chinese: hasTraditionalChinese,
    output_chars: text.length
  };
}

async function callModel(def, runIndex) {
  if (!def.url || !def.model) {
    const quality = textQuality('', 'missing url or model');
    return {
      benchmark_id: benchmarkId,
      row_type: 'run',
      provider: def.provider,
      model_label: def.label,
      model: def.model || '',
      run_index: runIndex,
      skipped: true,
      error: 'missing url or model',
      latency_ms: null,
      prompt_tokens: 0,
      completion_tokens: 0,
      total_tokens: 0,
      estimated_cost_usd: 0,
      output_preview: '',
      ...quality
    };
  }

  const started = Date.now();
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (def.apiKey) headers.Authorization = `Bearer ${def.apiKey}`;

    const result = await this.helpers.httpRequest({
      method: 'POST',
      url: def.url,
      headers,
      body: buildBody(def.model),
      json: true,
      timeout: 120000
    });

    const latencyMs = Date.now() - started;
    const usage = usageOf(result);
    const content = result.choices?.[0]?.message?.content || result.output_text || '';
    const quality = textQuality(content, null);

    return {
      benchmark_id: benchmarkId,
      row_type: 'run',
      provider: def.provider,
      model_label: def.label,
      model: def.model,
      run_index: runIndex,
      skipped: false,
      error: '',
      latency_ms: latencyMs,
      prompt_tokens: usage.promptTokens,
      completion_tokens: usage.completionTokens,
      total_tokens: usage.totalTokens,
      estimated_cost_usd: estimateCost(usage, def.inputRate, def.outputRate),
      output_preview: String(content).slice(0, 300),
      ...quality
    };
  } catch (error) {
    const quality = textQuality('', error.message);
    return {
      benchmark_id: benchmarkId,
      row_type: 'run',
      provider: def.provider,
      model_label: def.label,
      model: def.model,
      run_index: runIndex,
      skipped: false,
      error: error.message,
      latency_ms: Date.now() - started,
      prompt_tokens: 0,
      completion_tokens: 0,
      total_tokens: 0,
      estimated_cost_usd: 0,
      output_preview: '',
      ...quality
    };
  }
}

function avg(values) {
  const clean = values.filter(v => typeof v === 'number' && Number.isFinite(v));
  if (!clean.length) return null;
  return clean.reduce((a, b) => a + b, 0) / clean.length;
}

function min(values) {
  const clean = values.filter(v => typeof v === 'number' && Number.isFinite(v));
  return clean.length ? Math.min(...clean) : null;
}

function max(values) {
  const clean = values.filter(v => typeof v === 'number' && Number.isFinite(v));
  return clean.length ? Math.max(...clean) : null;
}

const rows = [];
for (const modelDef of models) {
  for (let i = 1; i <= runsPerModel; i++) {
    rows.push(await callModel.call(this, modelDef, i));
  }
}

const summaries = models.map(def => {
  const runs = rows.filter(r => r.model_label === def.label);
  const successful = runs.filter(r => !r.error && !r.skipped);
  return {
    benchmark_id: benchmarkId,
    row_type: 'summary',
    provider: def.provider,
    model_label: def.label,
    model: def.model || '',
    run_index: 0,
    skipped: runs.every(r => r.skipped),
    error: successful.length ? '' : (runs[0]?.error || 'no successful runs'),
    latency_ms: avg(successful.map(r => r.latency_ms)),
    latency_min_ms: min(successful.map(r => r.latency_ms)),
    latency_max_ms: max(successful.map(r => r.latency_ms)),
    prompt_tokens: avg(successful.map(r => r.prompt_tokens)),
    completion_tokens: avg(successful.map(r => r.completion_tokens)),
    total_tokens: avg(successful.map(r => r.total_tokens)),
    estimated_cost_usd: avg(successful.map(r => r.estimated_cost_usd)),
    total_cost_usd_3runs: successful.reduce((sum, r) => sum + Number(r.estimated_cost_usd || 0), 0),
    quality_score: avg(successful.map(r => r.quality_score)),
    has_thought_leak: successful.some(r => r.has_thought_leak),
    has_traditional_chinese: successful.every(r => r.has_traditional_chinese),
    output_chars: avg(successful.map(r => r.output_chars)),
    output_preview: successful[0]?.output_preview || '',
    runs_successful: successful.length,
    runs_total: runs.length
  };
});

const bestSpeed = summaries
  .filter(s => typeof s.latency_ms === 'number')
  .sort((a, b) => a.latency_ms - b.latency_ms)[0]?.model_label || 'unknown';
const bestQuality = summaries
  .filter(s => typeof s.quality_score === 'number')
  .sort((a, b) => b.quality_score - a.quality_score)[0]?.model_label || 'unknown';
const lowestCost = summaries
  .filter(s => typeof s.estimated_cost_usd === 'number')
  .sort((a, b) => a.estimated_cost_usd - b.estimated_cost_usd)[0]?.model_label || 'unknown';

const comparison = {
  benchmark_id: benchmarkId,
  row_type: 'comparison',
  provider: 'all',
  model_label: 'comparison-table',
  model: models.map(m => m.model).join(' vs '),
  run_index: 0,
  skipped: false,
  error: '',
  latency_ms: null,
  prompt_tokens: null,
  completion_tokens: null,
  total_tokens: null,
  estimated_cost_usd: null,
  quality_score: null,
  has_thought_leak: summaries.some(s => s.has_thought_leak),
  has_traditional_chinese: summaries.every(s => s.has_traditional_chinese),
  output_chars: null,
  best_speed: bestSpeed,
  best_quality_proxy: bestQuality,
  lowest_cost: lowestCost,
  output_preview: JSON.stringify(summaries.map(s => ({
    model_label: s.model_label,
    model: s.model,
    avg_latency_ms: s.latency_ms,
    min_latency_ms: s.latency_min_ms,
    max_latency_ms: s.latency_max_ms,
    avg_total_tokens: s.total_tokens,
    avg_cost_usd: s.estimated_cost_usd,
    avg_quality_score: s.quality_score,
    thought_leak: s.has_thought_leak,
    success: `${s.runs_successful}/${s.runs_total}`
  })))
};

return [...rows, ...summaries, comparison].map(row => ({
  json: {
    created_at: new Date().toISOString(),
    workflow: 'ai-multimodel-3run-benchmark',
    policy_name: policyName,
    prompt_chars: prompt.length,
    max_tokens: maxTokens,
    runs_per_model: runsPerModel,
    ...row
  }
}));
